using LocalProductManager.Api.Data;
using Microsoft.EntityFrameworkCore;

namespace LocalProductManager.Api.Services;

public static class LiveStreamBidProductSchema
{
    public static async Task UpgradeAsync(AppDbContext db)
    {
        var sql = db.Database.IsNpgsql()
            ? """
              CREATE TABLE IF NOT EXISTS live_stream_bid_products (
                "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "SourceProductId" integer REFERENCES products("Id") ON DELETE SET NULL,
                "Uuid" varchar(64) NOT NULL,
                "Title" varchar(1000) NOT NULL,
                "Quantity" integer NOT NULL,
                "Inventory" integer NOT NULL DEFAULT 1,
                "UnitPrice" numeric(12,2) NOT NULL,
                "WeightGrams" numeric(12,4),
                "WeightOunces" numeric(12,4),
                "Material" varchar(300),
                "TotalCost" numeric(12,2),
                "ImportedFileName" varchar(260),
                "IsSold" boolean NOT NULL DEFAULT false,
                "SoldAt" timestamp with time zone,
                "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                "UpdatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP);
              ALTER TABLE live_stream_bid_products ADD COLUMN IF NOT EXISTS "IsSold" boolean NOT NULL DEFAULT false;
              ALTER TABLE live_stream_bid_products ADD COLUMN IF NOT EXISTS "SoldAt" timestamp with time zone;
              ALTER TABLE live_stream_bid_products ADD COLUMN IF NOT EXISTS "SourceProductId" integer REFERENCES products("Id") ON DELETE SET NULL;
              ALTER TABLE live_stream_bid_products ADD COLUMN IF NOT EXISTS "Inventory" integer NOT NULL DEFAULT 1;
              CREATE INDEX IF NOT EXISTS "IX_live_stream_bid_products_SourceProductId" ON live_stream_bid_products ("SourceProductId");
              CREATE UNIQUE INDEX IF NOT EXISTS "IX_live_stream_bid_products_Uuid"
                ON live_stream_bid_products ("Uuid");
              CREATE TABLE IF NOT EXISTS live_stream_bid_sales (
                "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "BidProductId" integer NOT NULL REFERENCES live_stream_bid_products("Id") ON DELETE RESTRICT,
                "ProductUuid" varchar(64) NOT NULL,
                "ProductTitle" varchar(1000) NOT NULL,
                "Quantity" integer NOT NULL,
                "Cost" numeric(12,2),
                "ActualSalePrice" numeric(12,2),
                "SalePriceRmb" numeric(12,2),
                "ExchangeRateRmbToUsd" numeric(12,6),
                "ExchangeRateDate" date,
                "Profit" numeric(12,2),
                "ProfitUsd" numeric(12,2),
                "SaleDate" date NOT NULL,
                "SoldAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
                "SoldBy" varchar(80) NOT NULL);
              DROP INDEX IF EXISTS "IX_live_stream_bid_sales_BidProductId";
              CREATE INDEX IF NOT EXISTS "IX_live_stream_bid_sales_BidProductId" ON live_stream_bid_sales ("BidProductId");
              CREATE INDEX IF NOT EXISTS "IX_live_stream_bid_sales_SaleDate" ON live_stream_bid_sales ("SaleDate");
              ALTER TABLE live_stream_bid_sales ADD COLUMN IF NOT EXISTS "SalePriceRmb" numeric(12,2);
              ALTER TABLE live_stream_bid_sales ADD COLUMN IF NOT EXISTS "ExchangeRateRmbToUsd" numeric(12,6);
              ALTER TABLE live_stream_bid_sales ADD COLUMN IF NOT EXISTS "ExchangeRateDate" date;
              ALTER TABLE live_stream_bid_sales ADD COLUMN IF NOT EXISTS "ProfitUsd" numeric(12,2);
              UPDATE live_stream_bid_products
              SET "TotalCost" = ROUND(("UnitPrice" * "Quantity") + (COALESCE("WeightGrams", 0) * 0.05), 2)
              WHERE "TotalCost" IS NULL;
              UPDATE live_stream_bid_sales AS sale
              SET "Cost" = product."TotalCost"
              FROM live_stream_bid_products AS product
              WHERE sale."BidProductId" = product."Id" AND sale."Cost" IS NULL;
              UPDATE live_stream_bid_sales
              SET "Profit" = "SalePriceRmb" - "Cost",
                  "ProfitUsd" = "ActualSalePrice" - ROUND("Cost" * "ExchangeRateRmbToUsd", 2)
              WHERE "Cost" IS NOT NULL AND "ActualSalePrice" IS NOT NULL
                AND "SalePriceRmb" IS NOT NULL AND "ExchangeRateRmbToUsd" IS NOT NULL
                AND ("Profit" IS NULL OR "ProfitUsd" IS NULL);
              """
            : """
              CREATE TABLE IF NOT EXISTS live_stream_bid_products (
                Id INTEGER NOT NULL CONSTRAINT PK_live_stream_bid_products PRIMARY KEY AUTOINCREMENT,
                SourceProductId INTEGER NULL REFERENCES products(Id) ON DELETE SET NULL,
                Uuid TEXT NOT NULL,
                Title TEXT NOT NULL,
                Quantity INTEGER NOT NULL,
                Inventory INTEGER NOT NULL DEFAULT 1,
                UnitPrice TEXT NOT NULL,
                WeightGrams TEXT NULL,
                WeightOunces TEXT NULL,
                Material TEXT NULL,
                TotalCost TEXT NULL,
                ImportedFileName TEXT NULL,
                IsSold INTEGER NOT NULL DEFAULT 0,
                SoldAt TEXT NULL,
                CreatedAt TEXT NOT NULL,
                UpdatedAt TEXT NOT NULL);
              CREATE UNIQUE INDEX IF NOT EXISTS IX_live_stream_bid_products_Uuid
                ON live_stream_bid_products (Uuid);
              CREATE INDEX IF NOT EXISTS IX_live_stream_bid_products_SourceProductId ON live_stream_bid_products (SourceProductId);
              CREATE TABLE IF NOT EXISTS live_stream_bid_sales (
                Id INTEGER NOT NULL CONSTRAINT PK_live_stream_bid_sales PRIMARY KEY AUTOINCREMENT,
                BidProductId INTEGER NOT NULL REFERENCES live_stream_bid_products(Id) ON DELETE RESTRICT,
                ProductUuid TEXT NOT NULL,
                ProductTitle TEXT NOT NULL,
                Quantity INTEGER NOT NULL,
                Cost TEXT NULL,
                ActualSalePrice TEXT NULL,
                SalePriceRmb TEXT NULL,
                ExchangeRateRmbToUsd TEXT NULL,
                ExchangeRateDate TEXT NULL,
                Profit TEXT NULL,
                ProfitUsd TEXT NULL,
                SaleDate TEXT NOT NULL,
                SoldAt TEXT NOT NULL,
                SoldBy TEXT NOT NULL);
              DROP INDEX IF EXISTS IX_live_stream_bid_sales_BidProductId;
              CREATE INDEX IF NOT EXISTS IX_live_stream_bid_sales_BidProductId ON live_stream_bid_sales (BidProductId);
              CREATE INDEX IF NOT EXISTS IX_live_stream_bid_sales_SaleDate ON live_stream_bid_sales (SaleDate);
              UPDATE live_stream_bid_products SET TotalCost = ROUND((UnitPrice * Quantity) + (COALESCE(WeightGrams, 0) * 0.05), 2) WHERE TotalCost IS NULL;
              UPDATE live_stream_bid_sales
              SET Cost = (SELECT TotalCost FROM live_stream_bid_products WHERE Id = live_stream_bid_sales.BidProductId)
              WHERE Cost IS NULL;
              """;

        await db.Database.ExecuteSqlRawAsync(sql);
    }
}
